import hashlib
import json

from mt5_extracao.analytics import mention_classifier,mention_qualification

CASES = json.loads('[{"id": "eval-1", "text": "I love the Nova product because it works perfectly.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-2", "text": "Nova is a wonderful tool for our daily work.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-3", "text": "Nova is excellent and easy to use.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-4", "text": "I really like Nova and recommend it to friends.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-5", "text": "Nova is reliable and helpful for our whole team.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-6", "text": "We love Nova because its service is fantastic.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-7", "text": "Nova is impressive and very useful.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-8", "text": "Nova is not bad and I am happy with it.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-9", "text": "I admire Nova for its outstanding support.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-10", "text": "Nova is brilliant, safe and trustworthy.", "aliases": ["Nova"], "language": "en", "expected": "positive"}, {"id": "eval-11", "text": "I hate Nova because its service is terrible.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-12", "text": "Nova is awful and completely unreliable.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-13", "text": "Nova is a disappointing product for our team.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-14", "text": "I dislike Nova because it is useless.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-15", "text": "Nova is horrible and frustrating to use.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-16", "text": "We hate Nova because the support is dreadful.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-17", "text": "Nova is bad and very annoying.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-18", "text": "Nova is not good and it makes me miserable.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-19", "text": "I regret using Nova because it is disastrous.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-20", "text": "Nova is poor and untrustworthy.", "aliases": ["Nova"], "language": "en", "expected": "negative"}, {"id": "eval-21", "text": "Nova is available for download this morning.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-22", "text": "Nova has a new version on the website.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-23", "text": "Nova is a product mentioned in this report.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-24", "text": "Nova is scheduled for discussion at the meeting.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-25", "text": "Nova was launched in the year twenty twenty.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-26", "text": "Nova is on the list of applications we reviewed.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-27", "text": "Nova has an office in the city center.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-28", "text": "Nova is mentioned in the documentation.", "aliases": ["Nova"], "language": "en", "expected": "neutral"}, {"id": "eval-29", "text": "Nova is excellent but Nova is unreliable.", "aliases": ["Nova"], "language": "en", "expected": "mixed"}, {"id": "eval-30", "text": "Nova is wonderful. Nova is terrible.", "aliases": ["Nova"], "language": "en", "expected": "mixed"}, {"id": "eval-31", "text": "I love Nova but I hate Nova.", "aliases": ["Nova"], "language": "en", "expected": "mixed"}, {"id": "eval-32", "text": "Nova is useful but Nova is frustrating.", "aliases": ["Nova"], "language": "en", "expected": "mixed"}, {"id": "eval-33", "text": "Nova will rise by ten percent tomorrow.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-34", "text": "Nova stock is going down after the opening.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-35", "text": "Great, Nova broke again /s", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-36", "text": "Is Nova actually any good for my company?", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-37", "text": "They say Nova is excellent, according to an anonymous source.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-38", "text": "Buy Nova now and use my discount code!", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-39", "text": "Nova is better than Orion in every way.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-40", "text": "Orion is awful and Nova was mentioned in the same report.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-41", "text": "Nova é uma ferramenta muito boa para trabalhar.", "aliases": ["Nova"], "language": "pt", "expected": "abstained"}, {"id": "eval-42", "text": "Nova es una herramienta excelente para nuestro equipo.", "aliases": ["Nova"], "language": "es", "expected": "abstained"}, {"id": "eval-43", "text": "Nova is wonderful, said the spokesperson.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}, {"id": "eval-44", "text": "Nova stock price has gained five percent today.", "aliases": ["Nova"], "language": "en", "expected": "abstained"}]')


def test_frozen_controlled_benchmark_reproduces_qualified_confusion_without_relabeling():
    report=mention_qualification.REPORT
    raw=json.dumps(CASES,ensure_ascii=False,indent=2)+'\n'
    assert hashlib.sha256(raw.encode()).hexdigest()==report['evaluation_sha256']
    actual=Counter((case['expected'],mention_classifier.classify_document(case['text'],case['aliases'],language=case['language'])['label']) for case in CASES)
    assert [dict(expected=a,predicted=b,count=n) for (a,b),n in sorted(actual.items())]==report['confusion']
    assert mention_classifier.descriptor()==report['classifier']
